const root=path.resolve('runtime'),load=n=>import(pathToFileURL(path.join(root,'src/liquidation-extension',n))),require=createRequire(path.join(root,'src/liquidation-extension/package.json'));
const [collector,admission,budgets,bridge,allowances]=await Promise.all(['gtrade-runtime-collector.mjs','d1-source-admission.mjs','run-source-budget.mjs','gtrade-runtime-bridge.mjs','install-source-allowances.mjs'].map(load));
assert.equal(require('@gainsnetwork/sdk/package.json').version,'1.8.10');const sdk=require('@gainsnetwork/sdk');
const started=Date.now(),run_id=`GTRADE_ACTUAL_RPC_FAILURE:${process.env.GITHUB_RUN_ID}:${started}`,reservation={rows_read:1500,rows_written:100},db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),raw=[],sha=b=>createHash('sha256').update(b).digest('hex');
const proof={schema:'GTRADE_ACTUAL_RPC_FAILURE_DIAGNOSTIC_20261007_V1',github_head:process.env.GITHUB_SHA,run_id,started_ts:started,contract:'RAY-USDT',reason:'Natural actual Top2 report37628961697 at834619f RAY failed pinned RPC with GTRADE_PINNED_RPC_RESPONSE_INVALID. Retain the missing exact error and verify the same bounded current native route; no unchanged MAIN or Telegram replay.',source_http_cap:4,MAIN:0,Telegram:0,forced_candidate_report:false,source_clock_refreshed:false,full_market_coverage:false,new_fresh_SENT:false};let reserved=false,budget=null;
const within=e=>evaluateWithinRunReservation({reservation,currentUsage:db.usageSnapshot(),extraRowsRead:e.rows_read+80,extraRowsWritten:e.rows_written+10});
fs.mkdirSync('audit-output',{recursive:true});
try{
 const uni=JSON.parse(gunzipSync(fs.readFileSync('checkpoints/htx-all-modes-crypto-futures-universe-20261004.json.gz')));assert.equal(uni.assets.length,102);assert.equal(uni.contracts.length,119);assert.ok(uni.assets.some(a=>a.symbol==='RAY'));
 proof.day_admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,started),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});assert.equal(proof.day_admission.allowed,true,'D1_DAY_NOT_ADMITTED');proof.d1_reservation=await reserveRunBudget(db,{reservationId:run_id,now:started,reservation});reserved=true;
 const scope_id=`${allowances.LIQUIDATION_ALLOWANCE_GENERATION}:${new Date(started).toISOString().slice(0,7).replace('-','')}:GTRADE`,cfg=await db.prepare('SELECT * FROM report2_liq_source_allowance_shadow WHERE scope_id=?1 LIMIT 1').bind(scope_id).first();assert.equal(cfg?.active,1);assert.equal(cfg?.allowance_units,4000);assert.equal(cfg?.unit,'REQUEST');
 const provider_admit=admission.createD1SourceAdmission({db,scope_bindings:{GTRADE:{scope_id,config_fingerprint:cfg.config_fingerprint}},within_run_budget:e=>within({rows_read:e.extraRowsRead,rows_written:e.extraRowsWritten})});
 const capture=async(url,init)=>{const t=Date.now(),r=await fetch(url,init),reader=r.clone().body.getReader(),parts=[];let count=0;try{while(true){const x=await reader.read();if(x.done)break;count+=x.value.byteLength;if(count>8000000){await reader.cancel();throw Error('CAPTURE_RESPONSE_SIZE_LIMIT');}parts.push(Buffer.from(x.value));}}catch(e){await r.body?.cancel();throw e;}const bytes=Buffer.concat(parts);raw.push({url:String(url),method:init.method||'GET',request_body:init.body?JSON.parse(init.body):null,http_status:r.status,started_ts:t,received_ts:Date.now(),sha256:sha(bytes),payload:JSON.parse(bytes.toString('utf8'))});return r;};
 budget=budgets.createSharedSourceBudget({provider_admit,fetch_impl:capture,max_requests:4});const deadline=Date.now()+45000;proof.provider_admission=await budget.admit({reservation_id:run_id+':CURRENT_RAY_NATIVE',run_id,contract:'RAY-USDT',requests:{GTRADE:4},max_requests:4,deadline_ts:deadline});assert.equal(proof.provider_admission.allowed,true);assert.equal(proof.provider_admission.new_reservation,true);
 const collect=collector.createGTradeRuntimeCollector({sdk,fetch_impl:budget.fetch,reserve_rpc_enabled:true}),result=await collect({contract:'RAY-USDT',native_symbol:'RAY',run_id,acquisition_id:run_id+':RAY',deadline_ts:deadline,snapshot_admitted:true,admit_position_snapshot:async()=>({allowed:true,new_reservation:true,scope:'ALREADY_DURABLY_RESERVED_WITHIN_THIS_FOUR_REQUEST_RESEARCH_RUN'}),position_batch_contracts:['RAY-USDT']});proof.collection=result;
 const rpc=raw.find(x=>x.method==='POST');proof.rpc_response_errors=Array.isArray(rpc?.payload)?rpc.payload.filter(x=>x.error).map(x=>({id:x.id,code:x.error.code,message:String(x.error.message||'').replace(/[\x00-\x1f]/g,' ').slice(0,240),data:typeof x.error.data==='string'?x.error.data.slice(0,240):null,method:rpc.request_body.find(b=>b.id===x.id)?.method,selector:rpc.request_body.find(b=>b.id===x.id)?.params?.[0]?.data?.slice(0,10)??null})):[];
 proof.pinned_body=rpc?.request_body??null;proof.rpc_receipt=rpc?{url:rpc.url,http_status:rpc.http_status,sha256:rpc.sha256,received_ts:rpc.received_ts}:null;
 if(result.acquisition){const observed_ts=Date.now();proof.scoped_consumer=bridge.bindGTradeAcquisition(result.acquisition,{contract:'RAY-USDT',run_id,snapshot_id:run_id+':SOURCE_REFERENCE_ONLY',observed_ts});proof.observed_ts=observed_ts;proof.future_levels=proof.scoped_consumer.status==='USABLE_SCOPED_NATIVE_CONTEXT'?[...(proof.scoped_consumer.above||[]),...(proof.scoped_consumer.below||[])].length:0;}else proof.future_levels=0;
 proof.status=result.position_source_clock_known===true?'ACTUAL_CURRENT_PINNED_RAY_NATIVE_AND_SCOPED_CONTEXT_VERIFIED':'ACTUAL_CURRENT_NATIVE_ROUTE_ERROR_RETAINED_NOT_LEVEL_COVERAGE';assert.ok(budget.summary().actual_http<=4);assert.equal(db.usageSnapshot().unknown_ops,0);
}catch(e){proof.status='ACTUAL_RPC_DIAGNOSTIC_NOT_CLOSED';proof.error=String(e.message).slice(0,240);}
finally{if(reserved)try{proof.finalized_usage=await finalizeRunUsage(db,{reservationId:run_id,sourceRunId:String(process.env.GITHUB_RUN_ID),usage:db.usageSnapshot()});}catch(e){proof.status='ACTUAL_RPC_DIAGNOSTIC_NOT_CLOSED';proof.finalization_error=String(e.message).slice(0,200);}}
proof.completed_ts=Date.now();proof.shared_budget=budget?.summary()??null;proof.source_http=proof.shared_budget?.actual_http??0;proof.d1_usage=db.usageSnapshot();const bytes=gzipSync(Buffer.from(JSON.stringify({head:process.env.GITHUB_SHA,run_id,raw})));proof.raw_gzip_sha256=sha(bytes);fs.writeFileSync('audit-output/gtrade-actual-rpc-raw.json.gz',bytes);fs.writeFileSync('audit-output/gtrade-actual-rpc-proof.json',JSON.stringify(proof,null,2)+'\n');console.log(JSON.stringify({status:proof.status,run_id,source_http:proof.source_http,pinned_status:proof.collection?.pinned_position_status,pinned_reason:proof.collection?.pinned_position_reason,rpc_response_errors:proof.rpc_response_errors,levels:proof.future_levels,MAIN:0,Telegram:0,error:proof.error??null}));if(proof.status==='ACTUAL_RPC_DIAGNOSTIC_NOT_CLOSED')process.exitCode=1;
